from functools import partial, update_wrapper, wraps
from django.utils.decorators import method_decorator

class DummyLogger:
    def debug(self, msg):
        print(f"DEBUG: {msg}")

dummy_logger = DummyLogger()

def logger(func):
    @wraps(func)
    def inner(*args, **kwargs):
        try:
            result = func(*args, **kwargs)
        except Exception as e:
            result = str(e)
        finally:
            dummy_logger.debug(f"{func.__name__} called with args: {args} and kwargs: {kwargs} resulting: {result}")
        return result
    return inner

# Monkeypatch _multi_decorate to test the fix
import django.utils.decorators as dec_mod
original_multi_decorate = dec_mod._multi_decorate

def patched_multi_decorate(decorators, method):
    import functools
    if hasattr(decorators, '__iter__'):
        decorators = decorators[::-1]
    else:
        decorators = [decorators]

    def _wrapper(self, *args, **kwargs):
        bound_method = partial(method.__get__(self, type(self)))
        # The fix:
        update_wrapper(bound_method, method)
        for dec in decorators:
            bound_method = dec(bound_method)
        return bound_method(*args, **kwargs)

    for dec in decorators:
        dec_mod._update_method_wrapper(_wrapper, dec)
    update_wrapper(_wrapper, method)
    return _wrapper

dec_mod._multi_decorate = patched_multi_decorate
dec_mod.method_decorator = dec_mod.method_decorator  # This uses the patched _multi_decorate

class Test:
